  "proposed_task": {
    "title": "Qualify current slot compiler layout, accessors, constants, interning, and digests",
    "type": "task",
    "status": "open",
    "parent": "vb-eirmk",
    "metadata": {
      "master_requirement_ids": [
        "phase:11"
      ],
      "qualification_only": true
    },
    "description": "Qualify each current Slot compiler family at the compiler/IR boundary: slot layout, accessor lowering, constants, symbol interning, and workflow digests. Reuse historical implementation owners and do not infer missing behavior from closed status.",
    "acceptance": [
      {
        "kind": "phase_specific_qualification",
        "clauses": [
          "Positive: bind source-visible slot declarations and references to exact stable slot layout and valid accessor/constant/symbol/digest outputs on representative current compiler inputs.",
          "Negative: bind out-of-range or unsupported slot/accessor references, invalid constant references, symbol-table boundary violations, and digest mismatch cases to exact typed rejection or deterministic mismatch behavior where the current contract specifies them.",
          "Keep slot layout, accessor tables, constant tables, symbol interning, and digest/parity evidence as separate ledger families; distinguish compile/parse parity from each family’s direct invariant checks.",
          "For every family, name production entry points and exact registered checks/properties; record source pin and raw receipts with separate CODE and independent TEST dispositions, leaving unexecuted proof/fuzz/benchmark obligations unknown."
        ]
      },
      {
        "kind": "per_clause_family_allocation",
        "clauses": [
          {
            "family": "slot layout and source-slot reservation",
            "existing_owner_ids": [
              "vb-ito"
            ],
            "allocation": "Reuse closed vb-ito as historical implementation owner; qualify layout and source-visible reservation independently."
          },
          {
            "family": "accessor lowering/table behavior",
            "existing_owner_ids": [
              "vb-mc8",
              "vb-rs5",
              "vb-ito"
            ],
            "allocation": "Reuse closed vb-mc8/vb-rs5 implementation records and vb-ito phase contract; keep accessor qualification separate from slot/constant checks."
          },
          {
            "family": "constant table and constant references",
            "existing_owner_ids": [
              "vb-ito"
            ],
            "allocation": "Reuse vb-ito historical ownership; map valid and invalid constant index/value behavior without proposing implementation work absent a reproduced defect."
          },
          {
            "family": "symbol interning and workflow digests",
            "existing_owner_ids": [
              "vb-ito"
            ],
            "allocation": "Reuse vb-ito historical ownership; separately map interning stability and digest identity/parity checks."
          }
        ]
      }
    ],
    "dependencies": []
  }
}
